import {
  parseIfraLimitFromProperties,
  resolveIfraStandard,
} from "./ifraStandards";

function localizeLongevity(val: string, lang: AppLanguage): string {
  if (!val || lang === "ru") return val;
  let res = val;
  const hours: Record<AppLanguage, string> = { ru: "часов", en: "hours", it: "ore", es: "horas", de: "Stunden" };
  const days: Record<AppLanguage, string> = { ru: "дней", en: "days", it: "giorni", es: "días", de: "Tage" };
  const weeks: Record<AppLanguage, string> = { ru: "недель", en: "weeks", it: "settimane", es: "semanas", de: "Wochen" };
  const months: Record<AppLanguage, string> = { ru: "месяцев", en: "months", it: "mesi", es: "meses", de: "Monate" };
  const minutes: Record<AppLanguage, string> = { ru: "мин", en: "min", it: "min", es: "min", de: "Min" };
  const over: Record<AppLanguage, string> = { ru: "более ", en: "over ", it: "oltre ", es: "más de ", de: "über " };
  const approx: Record<AppLanguage, string> = { ru: "около ", en: "approx. ", it: "circa ", es: "aprox. ", de: "ca. " };
  const upTo: Record<AppLanguage, string> = { ru: "до ", en: "up to ", it: "fino a ", es: "hasta ", de: "bis zu " };

  res = res
    .replace(/более\s+|больше\s+/giu, over[lang])
    .replace(/около\s+/giu, approx[lang])
    .replace(/до\s+/giu, upTo[lang])
    .replace(/3х/giu, "3")
    .replace(/(?:часов|часа|час|(?<=\d|\s)ч(?=\.|\s|$))/giu, hours[lang])
    .replace(/(?:суток|дней|дня|день)/giu, days[lang])
    .replace(/(?:недели|недель|неделя|неделю)/giu, weeks[lang])
    .replace(/(?:месяцев|месяца|месяц)/giu, months[lang])
    .replace(/(?:минут|минуты|минута)/giu, minutes[lang]);
  return res.trim();
}

function localizeConservatoryName(rawName: string, lang: AppLanguage): string {
  if (lang === "ru") return rawName;
  if (rawName.includes("/")) {
    const parts = rawName.split("/").map((p) => p.trim());
    if (parts.length === 2 && /[а-яА-ЯёЁ]/.test(parts[1])) {
      return parts[0].replace(/\s*кристаллическое\s+вещество/gi, " (Crystals)");
    }
  }
  return rawName.replace(/\s*кристаллическое\s+вещество/gi, " (Crystals)");
}

function localizeConservatoryProps(props: string, lang: AppLanguage): string {
  if (!props || lang === "ru") return props;
  let p = localizeLongevity(props, lang);
  if (lang === "en") {
    p = p
      .replace(/Источник\s*:/g, "Source:")
      .replace(/Производитель\s*:/g, "Manufacturer:")
      .replace(/Стойкость\s+на\s+блоттере\s*:/g, "Blotter longevity:")
      .replace(/на\s+блоттере/gi, "on blotter")
      .replace(/Ограничение\s+IFRA\s*:/g, "IFRA limit:")
      .replace(/не\s+ограничен[оа]?|без\s+ограничений/gi, "not restricted")
      .replace(/ЗАПРЕЩЕНО/g, "PROHIBITED")
      .replace(/до\s+(\d)/g, "up to $1");
  } else if (lang === "it") {
    p = p
      .replace(/Источник\s*:/g, "Fonte:")
      .replace(/Производитель\s*:/g, "Produttore:")
      .replace(/Стойкость\s+на\s+блоттере\s*:/g, "Persistenza su mouillette:")
      .replace(/на\s+блоттере/gi, "su mouillette")
      .replace(/Ограничение\s+IFRA\s*:/g, "Limite IFRA:")
      .replace(/не\s+ограничен[оа]?|без\s+ограничений/gi, "non limitato")
      .replace(/ЗАПРЕЩЕНО/g, "PROIBITO")
      .replace(/до\s+(\d)/g, "fino a $1");
  } else if (lang === "es") {
    p = p
      .replace(/Источник\s*:/g, "Fuente:")
      .replace(/Производитель\s*:/g, "Fabricante:")
      .replace(/Стойкость\s+на\s+блоттере\s*:/g, "Persistencia en secante:")
      .replace(/на\s+блоттере/gi, "en secante")
      .replace(/Ограничение\s+IFRA\s*:/g, "Límite IFRA:")
      .replace(/не\s+ограничен[оа]?|без\s+ограничений/gi, "no restringido")
      .replace(/ЗАПРЕЩЕНО/g, "PROHIBIDO")
      .replace(/до\s+(\d)/g, "hasta $1");
  } else if (lang === "de") {
    p = p
      .replace(/Источник\s*:/g, "Quelle:")
      .replace(/Производитель\s*:/g, "Hersteller:")
      .replace(/Стойкость\s+на\s+блоттере\s*:/g, "Haltbarkeit auf Riechstreifen:")
      .replace(/на\s+блоттере/gi, "auf Riechstreifen")
      .replace(/Ограничение\s+IFRA\s*:/g, "IFRA-Grenzwert:")
      .replace(/не\s+ограничен[оа]?|без\s+ограничений/gi, "nicht beschränkt")
      .replace(/ЗАПРЕЩЕНО/g, "VERBOTEN")
      .replace(/до\s+(\d)/g, "bis zu $1");
  }
  return p;
}

function buildNormalizedConservatoryItem(
  tuple: Src3Tuple,
  idx: number,
  language: AppLanguage
): LibraryIngredient {
  const [id, rawName, casOrSource, family, tier, origin, subst, scent, props] = tuple;
  const name = localizeConservatoryName(rawName, language);
  const std = resolveIfraStandard({ name: rawName, inciOrCas: casOrSource });
  const parsedPropLimit = parseIfraLimitFromProperties(props);

  let ifraLimitPercent: number | undefined = parsedPropLimit;
  let normalizedProps = props
    .replace(/\s*Рекомендуемый\s+ввод\s*:[^.]*(?:\.|$)/gi, "")
    .trim();

  if (std) {
    if (std.status === "exempt_fcf") {
      ifraLimitPercent = undefined;
      const replacementSentence =
        language === "ru"
          ? "IFRA 51 Cat. 4: FCF (не ограничен)."
          : language === "it"
          ? "IFRA 51 Cat. 4: FCF (non limitato)."
          : language === "es"
          ? "IFRA 51 Cat. 4: FCF (no restringido)."
          : language === "de"
          ? "IFRA 51 Cat. 4: FCF (nicht beschränkt)."
          : "IFRA 51 Cat. 4: FCF (not restricted).";
      if (/Ограничение\s+IFRA\s*:[^.]*\./i.test(normalizedProps)) {
        normalizedProps = normalizedProps.replace(/Ограничение\s+IFRA\s*:[^.]*\./i, replacementSentence);
      } else {
        normalizedProps = `${normalizedProps} ${replacementSentence}`.trim();
      }
    } else if (std.status === "unrestricted") {
      ifraLimitPercent = undefined;
      const replacementSentence =
        language === "ru"
          ? "IFRA 51 Cat. 4: не ограничен."
          : language === "it"
          ? "IFRA 51 Cat. 4: non limitato."
          : language === "es"
          ? "IFRA 51 Cat. 4: no restringido."
          : language === "de"
          ? "IFRA 51 Cat. 4: nicht beschränkt."
          : "IFRA 51 Cat. 4: not restricted.";
      if (/Ограничение\s+IFRA\s*:[^.]*\./i.test(normalizedProps)) {
        normalizedProps = normalizedProps.replace(/Ограничение\s+IFRA\s*:[^.]*\./i, replacementSentence);
      } else {
        normalizedProps = `${normalizedProps} ${replacementSentence}`.trim();
      }
    } else {
      ifraLimitPercent = std.category4LimitPercent;
      const replacementSentence =
        std.category4LimitPercent === 0
          ? language === "ru"
            ? "IFRA 51 Cat. 4: ЗАПРЕЩЕНО (0%)."
            : language === "it"
            ? "IFRA 51 Cat. 4: PROIBITO (0%)."
            : language === "es"
            ? "IFRA 51 Cat. 4: PROHIBIDO (0%)."
            : language === "de"
            ? "IFRA 51 Cat. 4: VERBOTEN (0%)."
            : "IFRA 51 Cat. 4: PROHIBITED (0%)."
          : language === "ru"
          ? `IFRA 51 Cat. 4: до ${std.category4LimitPercent}%.`
          : language === "it"
          ? `IFRA 51 Cat. 4: fino a ${std.category4LimitPercent}%.`
          : language === "es"
          ? `IFRA 51 Cat. 4: hasta ${std.category4LimitPercent}%.`
          : language === "de"
          ? `IFRA 51 Cat. 4: bis zu ${std.category4LimitPercent}%.`
          : `IFRA 51 Cat. 4: up to ${std.category4LimitPercent}%.`;
      if (/Ограничение\s+IFRA\s*:[^.]*\./i.test(normalizedProps)) {
        normalizedProps = normalizedProps.replace(/Ограничение\s+IFRA\s*:[^.]*\./i, replacementSentence);
      } else {
        normalizedProps = `${normalizedProps} ${replacementSentence}`.trim();
      }
    }
  }

  normalizedProps = localizeConservatoryProps(normalizedProps, language);

  return {
    id,
    name,
    inciOrCas: casOrSource,
    family,
    tier: std?.id === "ifra-unres-dpg" ? "solvent" : tier,
    origin,
    blotterLongevity: localizeLongevity(subst, language),
    ifraLimitPercent,
    properties: normalizedProps,
    scentDescription: scent,
    scentRating: origin === "natural" || casOrSource.includes("IFF") ? 9 : 8,
    futureIdeasRating: idx % 3 === 0 ? 9 : 8,
    notes: [],
    createdAt: "2026-11-14",
    updatedAt: "2026-11-14",
  };
}

export function getFragranceConservatoryLibrary(language: AppLanguage): LibraryIngredient[] {
  return SRC3_TUPLES.map((tuple, idx) => buildNormalizedConservatoryItem(tuple, idx, language));
}
